// gping-compatible reimplementation (stdlib only)

use std::env;
use std::fmt::{self, Write as FmtWrite};
use std::io::{self, Read, Write};
use std::net::ToSocketAddrs;
use std::process;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

mod cli;
mod color;
mod term;
mod tui;

use cli::{Args, CliError};

const SHORT_VERSION: &str = "gping 1.20.1";
const LONG_VERSION: &str = "gping 1.20.1\ncommit_hash: d67d2aeb\nbuild_time: 2026-04-17 19:59:37 +00:00\nbuild_env: rustc 1.92.0 (ded5c06cf 2025-12-08),1.92.0-x86_64-unknown-linux-gnu";

fn main() {
    let args: Vec<String> = env::args().collect();
    let prog = args.get(0).map(|s| {
        std::path::Path::new(s)
            .file_name()
            .map(|n| n.to_string_lossy().to_string())
            .unwrap_or_else(|| s.clone())
    }).unwrap_or_else(|| "executable".into());

    let parsed = cli::parse(&args[1..], &prog);
    let parsed = match parsed {
        Ok(cli::ParseResult::Args(a)) => a,
        Ok(cli::ParseResult::Help) => {
            print!("{}", cli::help_text(&prog));
            process::exit(0);
        }
        Ok(cli::ParseResult::ShortVersion) => {
            println!("{}", SHORT_VERSION);
            process::exit(0);
        }
        Ok(cli::ParseResult::LongVersion) => {
            println!("{}", LONG_VERSION);
            process::exit(0);
        }
        Err(e) => {
            match e {
                CliError::Usage(msg) => {
                    eprint!("{}", msg);
                    process::exit(2);
                }
            }
        }
    };

    if let Err(e) = run(parsed) {
        eprintln!("Error: {}", e.message);
        if let Some(cause) = e.cause {
            eprintln!("\nCaused by:\n    {}", cause);
        }
        process::exit(1);
    }
}

struct AppError {
    message: String,
    cause: Option<String>,
}

fn mkerr(msg: impl Into<String>) -> AppError {
    AppError { message: msg.into(), cause: None }
}

fn mkerr2(msg: impl Into<String>, cause: impl Into<String>) -> AppError {
    AppError { message: msg.into(), cause: Some(cause.into()) }
}

fn expand_cloud_shorthand(host: &str) -> String {
    // "aws:<region>" -> ec2.<region>.amazonaws.com
    if let Some(rest) = host.strip_prefix("aws:") {
        return format!("ec2.{}.amazonaws.com", rest);
    }
    host.to_string()
}

fn run(args: Args) -> Result<(), AppError> {
    // First: require at least one host/command.
    if args.hosts_or_commands.is_empty() {
        return Err(mkerr(
            "At least one host or command must be given (i.e gping google.com). Use --help for a full list of arguments.",
        ));
    }

    // Validate colors (only up to number of hosts, matching observed behavior).
    let color_codes: Vec<String> = args.colors.iter().take(args.hosts_or_commands.len()).cloned().collect();
    let parsed_colors = color::parse_colors(&color_codes).map_err(|bad| {
        AppError {
            message: format!("Invalid color code: `{}`", bad),
            cause: Some("Failed to parse Colors".to_string()),
        }
    })?;

    if !args.cmd {
        // Ping mode
        // DNS resolve each host (show first failing one).
        let mut resolved = Vec::new();
        for h in &args.hosts_or_commands {
            let target = expand_cloud_shorthand(h);
            let addrs = dns_resolve(&target, args.ipv4, args.ipv6);
            match addrs {
                Ok(v) if !v.is_empty() => resolved.push((h.clone(), target.clone(), v)),
                Ok(_) => {
                    return Err(mkerr2(
                        format!("Resolving {}", target),
                        "failed to lookup address information: No address associated with hostname",
                    ));
                }
                Err(msg) => {
                    return Err(mkerr2(format!("Resolving {}", target), msg));
                }
            }
        }
        tui::run_ping(&args, &resolved, &parsed_colors)
    } else {
        // Command mode
        tui::run_cmd(&args, &parsed_colors)
    }
}

fn dns_resolve(host: &str, ipv4: bool, ipv6: bool) -> Result<Vec<std::net::IpAddr>, String> {
    // Strip any port, append :0 if needed.
    let with_port = format!("{}:0", host);
    match with_port.to_socket_addrs() {
        Ok(iter) => {
            let mut v = Vec::new();
            for sa in iter {
                let ip = sa.ip();
                if ipv4 && !ip.is_ipv4() { continue; }
                if ipv6 && !ip.is_ipv6() { continue; }
                v.push(ip);
            }
            Ok(v)
        }
        Err(e) => Err(format!("failed to lookup address information: {}", map_dns_error(&e, host))),
    }
}

fn map_dns_error(e: &io::Error, _host: &str) -> String {
    // Try to match common libc messages
    let s = e.to_string();
    if s.contains("failed to lookup address information:") {
        if let Some(i) = s.find(": ") {
            return s[i + 2..].to_string();
        }
    }
    s
}
