// Minimal clap-compatible CLI parser tailored to gping's expected messages.

pub struct Args {
    pub cmd: bool,
    pub watch_interval: Option<f64>,
    pub buffer: u64,
    pub ipv4: bool,
    pub ipv6: bool,
    pub interface: Option<String>,
    pub simple_graphics: bool,
    pub vertical_margin: u16,
    pub horizontal_margin: u16,
    pub colors: Vec<String>, // flattened from comma-separated & repeated
    pub clear: bool,
    pub ping_args: Vec<String>,
    pub hosts_or_commands: Vec<String>,
}

pub enum ParseResult {
    Args(Args),
    Help,
    ShortVersion,
    LongVersion,
}

pub enum CliError {
    Usage(String),
}

// Specification for each option.
#[derive(Copy, Clone)]
enum OptKind {
    Flag,
    Value,
    MultiValue, // --ping-args: 0+ values that consume following args until next flag
}

fn fmt_usage_brief(prog: &str, active: Option<&str>) -> String {
    match active {
        None => format!("Usage: {} [OPTIONS] [HOSTS_OR_COMMANDS]...", prog),
        Some("-4") => format!("Usage: {} -4 [HOSTS_OR_COMMANDS]...", prog),
        Some("-6") => format!("Usage: {} -6 [HOSTS_OR_COMMANDS]...", prog),
        Some("-4h") => format!("Usage: {} -4 <HOSTS_OR_COMMANDS>...", prog),
        Some("-6h") => format!("Usage: {} -6 <HOSTS_OR_COMMANDS>...", prog),
        Some("--cmd") => format!("Usage: {} --cmd [HOSTS_OR_COMMANDS]...", prog),
        Some(other) => format!("Usage: {} {} [HOSTS_OR_COMMANDS]...", prog, other),
    }
}

fn usage_footer(prog: &str, brief_active: Option<&str>) -> String {
    let mut s = String::new();
    s.push_str(&fmt_usage_brief(prog, brief_active));
    s.push_str("\n\nFor more information, try '--help'.\n");
    s
}

pub fn help_text(prog: &str) -> String {
    let mut s = String::new();
    s.push_str("Ping, but with a graph.\n\n");
    s.push_str(&format!("Usage: {} [OPTIONS] [HOSTS_OR_COMMANDS]...\n\n", prog));
    s.push_str("Arguments:\n");
    s.push_str("  [HOSTS_OR_COMMANDS]...  Hosts or IPs to ping, or commands to run if --cmd is provided. Can use cloud shorthands like aws:eu-west-1\n\n");
    s.push_str("Options:\n");
    s.push_str("      --cmd\n");
    s.push_str("          Graph the execution time for a list of commands rather than pinging hosts\n");
    s.push_str("  -n, --watch-interval <WATCH_INTERVAL>\n");
    s.push_str("          Watch interval seconds (provide partial seconds like '0.5'). Default for ping is 0.2, default for cmd is 0.5\n");
    s.push_str("  -b, --buffer <BUFFER>\n");
