pub fn parse(input: &[String], prog: &str) -> Result<ParseResult, CliError> {
    // We manually parse clap-ish.
    let mut cmd = false;
    let mut watch_interval: Option<f64> = None;
    let mut buffer: Option<u64> = None;
    let mut ipv4 = false;
    let mut ipv6 = false;
    let mut interface: Option<String> = None;
    let mut simple_graphics = false;
    let mut vertical_margin: Option<u16> = None;
    let mut horizontal_margin: Option<u16> = None;
    let mut colors: Vec<String> = Vec::new();
    let mut any_color_given = false;
    let mut clear = false;
    let mut ping_args_given = false;
    let mut ping_args: Vec<String> = Vec::new();
    let mut hosts: Vec<String> = Vec::new();

    let mut i = 0;
    let mut after_dd = false;
    while i < input.len() {
        let arg = &input[i];
        if after_dd {
            hosts.push(arg.clone());
            i += 1;
            continue;
        }
        if arg == "--" {
            after_dd = true;
            i += 1;
            continue;
        }
        if arg.starts_with("--") {
            // long option
            let (name, val_opt) = match arg.find('=') {
                Some(idx) => (&arg[..idx], Some(arg[idx + 1..].to_string())),
                None => (arg.as_str(), None),
            };
            match name {
                "--help" => return Ok(ParseResult::Help),
                "--version" => return Ok(ParseResult::LongVersion),
                "--cmd" => {
                    if val_opt.is_some() {
                        // clap treats --cmd=x as error because it's a flag
                        return Err(err_invalid_value(prog, "--cmd", val_opt.as_ref().unwrap(), "expected no argument"));
                    }
                    if cmd { return Err(err_multiple(prog, "--cmd")); }
                    if ping_args_given { return Err(err_conflict(prog, "--cmd", "--ping-args [<PING_ARGS>...]")); }
                    cmd = true;
                    i += 1;
                }
                "--watch-interval" => {
                    let v = take_value(name, val_opt, input, &mut i, prog)?;
                    if watch_interval.is_some() { return Err(err_multiple(prog, "--watch-interval <WATCH_INTERVAL>")); }
                    let f = parse_float(&v, "--watch-interval <WATCH_INTERVAL>", prog)?;
                    watch_interval = Some(f);
                }
                "--buffer" => {
                    let v = take_value(name, val_opt, input, &mut i, prog)?;
                    if buffer.is_some() { return Err(err_multiple(prog, "--buffer <BUFFER>")); }
                    let b = parse_uint(&v, "u64", prog, "--buffer <BUFFER>")?;
                    buffer = Some(b);
                }
                "--interface" => {
                    let v = take_value(name, val_opt, input, &mut i, prog)?;
                    if interface.is_some() { return Err(err_multiple(prog, "--interface <INTERFACE>")); }
                    interface = Some(v);
                }
                "--simple-graphics" => {
                    if val_opt.is_some() {
                        return Err(err_invalid_value(prog, "--simple-graphics", val_opt.as_ref().unwrap(), "expected no argument"));
                    }
                    if simple_graphics { return Err(err_multiple(prog, "--simple-graphics")); }
                    simple_graphics = true;
                    i += 1;
                }
                "--vertical-margin" => {
                    let v = take_value(name, val_opt, input, &mut i, prog)?;
                    if vertical_margin.is_some() { return Err(err_multiple(prog, "--vertical-margin <VERTICAL_MARGIN>")); }
                    let n = parse_u16_arg(&v, "--vertical-margin <VERTICAL_MARGIN>", prog)?;
                    vertical_margin = Some(n);
                }
                "--horizontal-margin" => {
                    let v = take_value(name, val_opt, input, &mut i, prog)?;
                    if horizontal_margin.is_some() { return Err(err_multiple(prog, "--horizontal-margin <HORIZONTAL_MARGIN>")); }
                    let n = parse_u16_arg(&v, "--horizontal-margin <HORIZONTAL_MARGIN>", prog)?;
                    horizontal_margin = Some(n);
                }
                "--color" => {
                    let v = take_value(name, val_opt, input, &mut i, prog)?;
                    any_color_given = true;
                    // Empty string → no colors added
                    if !v.is_empty() {
                        for c in v.split(',') {
                            colors.push(c.to_string());
                        }
                    }
                }
                "--clear" => {
                    if val_opt.is_some() {
                        return Err(err_invalid_value(prog, "--clear", val_opt.as_ref().unwrap(), "expected no argument"));
                    }
                    if clear { return Err(err_multiple(prog, "--clear")); }
                    clear = true;
                    i += 1;
                }
                "--ping-args" => {
                    if cmd { return Err(err_conflict(prog, "--ping-args [<PING_ARGS>...]", "--cmd")); }
                    if ping_args_given { return Err(err_multiple(prog, "--ping-args [<PING_ARGS>...]")); }
                    ping_args_given = true;
                    // Consume value via `=` style OR slurp subsequent non-flag tokens.
                    if let Some(val) = val_opt {
                        if !val.is_empty() {
                            ping_args.push(val);
                        }
                        i += 1;
                    } else {
                        i += 1;
                        while i < input.len() {
                            let nxt = &input[i];
                            if nxt == "--" {
                                // Stop at --, don't consume
                                break;
                            }
                            // ping-args is greedy: per observation, it consumes even flag-like tokens
                            ping_args.push(nxt.clone());
                            i += 1;
                        }
                    }
                }
                _ => {
                    return Err(err_unexpected(prog, arg));
                }
            }
        } else if arg.starts_with('-') && arg.len() > 1 && arg != "-" {
            // short option(s) bundled. But first check if it's actually numeric like -5 (then it's an unexpected arg)
            let rest = &arg[1..];
            // If first char is a digit, treat as unexpected (like clap). Except -4 / -6 which are flags.
            let first = rest.chars().next().unwrap();
            // -4 and -6 are flags in our model. Other single digits are unexpected.
            if first.is_ascii_digit() && first != '4' && first != '6' {
                return Err(err_unexpected(prog, arg));
            }
            // Parse short options left-to-right.
            let mut chars: Vec<char> = rest.chars().collect();
            let mut idx = 0;
            while idx < chars.len() {
                let c = chars[idx];
                match c {
                    'h' => return Ok(ParseResult::Help),
                    'V' => return Ok(ParseResult::ShortVersion),
                    's' => {
                        if simple_graphics { return Err(err_multiple(prog, "--simple-graphics")); }
                        simple_graphics = true;
                        idx += 1;
                    }
                    '4' => {
                        if ipv4 { return Err(err_multiple(prog, "-4")); }
                        if ipv6 { return Err(err_conflict(prog, "-4", "-6")); }
                        ipv4 = true;
                        idx += 1;
                    }
                    '6' => {
                        if ipv6 { return Err(err_multiple(prog, "-6")); }
                        if ipv4 { return Err(err_conflict(prog, "-6", "-4")); }
                        ipv6 = true;
                        idx += 1;
                    }
                    'n' | 'b' | 'i' | 'c' => {
                        // value-taking. Remainder of chars (from idx+1 to end) is the value, else next arg.
                        let (long_name, display) = match c {
                            'n' => ("--watch-interval", "--watch-interval <WATCH_INTERVAL>"),
                            'b' => ("--buffer", "--buffer <BUFFER>"),
                            'i' => ("--interface", "--interface <INTERFACE>"),
                            'c' => ("--color", "--color <color>"),
                            _ => unreachable!(),
                        };
                        let val: String;
                        if idx + 1 < chars.len() {
                            val = chars[idx + 1..].iter().collect();
                            idx = chars.len();
                        } else {
                            // consume next arg
                            if i + 1 >= input.len() {
                                return Err(err_value_required(prog, display));
                            }
                            i += 1;
                            val = input[i].clone();
                            idx = chars.len();
                        }
                        match c {
                            'n' => {
                                if watch_interval.is_some() { return Err(err_multiple(prog, display)); }
                                watch_interval = Some(parse_float(&val, display, prog)?);
                            }
                            'b' => {
                                if buffer.is_some() { return Err(err_multiple(prog, display)); }
                                buffer = Some(parse_uint(&val, "u64", prog, display)?);
                            }
                            'i' => {
                                if interface.is_some() { return Err(err_multiple(prog, display)); }
                                interface = Some(val);
                            }
                            'c' => {
                                any_color_given = true;
                                if !val.is_empty() {
                                    for cc in val.split(',') {
                                        colors.push(cc.to_string());
                                    }
                                }
                            }
                            _ => unreachable!(),
                        }
                    }
                    _ => {
                        // unknown short
                        let tok = format!("-{}", c);
                        return Err(err_unexpected(prog, &tok));
                    }
                }
            }
            i += 1;
        } else {
            hosts.push(arg.clone());
            i += 1;
        }
    }

    // If -c was given but no value, that's handled by take_value already.

    Ok(ParseResult::Args(Args {
        cmd,
        watch_interval,
        buffer: buffer.unwrap_or(30),
        ipv4,
        ipv6,
        interface,
        simple_graphics,
        vertical_margin: vertical_margin.unwrap_or(1),
        horizontal_margin: horizontal_margin.unwrap_or(0),
        colors,
        clear,
        ping_args,
        hosts_or_commands: hosts,
    }))
}

fn take_value(
    name: &str,
    val_opt: Option<String>,
    input: &[String],
    i: &mut usize,
    prog: &str,
) -> Result<String, CliError> {
    // Returns a string and advances i past the option (and possibly value).
    let display = match name {
        "--watch-interval" => "--watch-interval <WATCH_INTERVAL>",
        "--buffer" => "--buffer <BUFFER>",
        "--interface" => "--interface <INTERFACE>",
        "--vertical-margin" => "--vertical-margin <VERTICAL_MARGIN>",
        "--horizontal-margin" => "--horizontal-margin <HORIZONTAL_MARGIN>",
        "--color" => "--color <color>",
        _ => name,
    };
    if let Some(v) = val_opt {
        // --name=val consumed; advance i
        *i += 1;
        return Ok(v);
    }
    if *i + 1 >= input.len() {
        return Err(err_value_required(prog, display));
    }
    *i += 2;
    Ok(input[*i - 1].clone())
}
