fn err_conflict(prog: &str, a: &str, b: &str) -> CliError {
    let mut s = String::new();
    s.push_str(&format!("error: the argument '{}' cannot be used with '{}'\n\n", a, b));
    // brief uses the first named flag
    let brief_act = Some(a);
    s.push_str(&fmt_usage_brief(prog, match a {
