    s.push_str("          following color names: 'black', 'red', 'green', 'yellow', 'blue', 'magenta',\n");
    s.push_str("          'cyan', 'gray', 'dark-gray', 'light-red', 'light-green', 'light-yellow',\n");
    s.push_str("          'light-blue', 'light-magenta', 'light-cyan', and 'white'\n");
    s.push_str("      --clear\n");
