// Color parsing

#[derive(Clone, Copy, Debug)]
pub struct Rgb(pub u8, pub u8, pub u8);

#[derive(Clone, Copy, Debug)]
pub enum Color {
    Named(NamedColor),
    Rgb(Rgb),
}

#[derive(Clone, Copy, Debug)]
pub enum NamedColor {
    Black, Red, Green, Yellow, Blue, Magenta, Cyan, Gray, DarkGray,
    LightRed, LightGreen, LightYellow, LightBlue, LightMagenta, LightCyan, White,
}

pub fn parse_color(s: &str) -> Option<Color> {
    let lower = s.to_ascii_lowercase();
    let named = match lower.as_str() {
        "black" => Some(NamedColor::Black),
        "red" => Some(NamedColor::Red),
        "green" => Some(NamedColor::Green),
        "yellow" => Some(NamedColor::Yellow),
        "blue" => Some(NamedColor::Blue),
        "magenta" => Some(NamedColor::Magenta),
        "cyan" => Some(NamedColor::Cyan),
        "gray" => Some(NamedColor::Gray),
        "dark-gray" => Some(NamedColor::DarkGray),
        "light-red" => Some(NamedColor::LightRed),
        "light-green" => Some(NamedColor::LightGreen),
        "light-yellow" => Some(NamedColor::LightYellow),
        "light-blue" => Some(NamedColor::LightBlue),
        "light-magenta" => Some(NamedColor::LightMagenta),
        "light-cyan" => Some(NamedColor::LightCyan),
        "white" => Some(NamedColor::White),
        _ => None,
    };
    if let Some(n) = named { return Some(Color::Named(n)); }
    // Try hex
    if let Some(rest) = s.strip_prefix('#') {
        if rest.len() == 6 && rest.chars().all(|c| c.is_ascii_hexdigit()) {
            let r = u8::from_str_radix(&rest[0..2], 16).ok()?;
            let g = u8::from_str_radix(&rest[2..4], 16).ok()?;
            let b = u8::from_str_radix(&rest[4..6], 16).ok()?;
            return Some(Color::Rgb(Rgb(r, g, b)));
        }
    }
    None
}

pub fn parse_colors(codes: &[String]) -> Result<Vec<Color>, String> {
    let mut out = Vec::new();
    for c in codes {
        match parse_color(c) {
            Some(col) => out.push(col),
            None => return Err(c.clone()),
        }
    }
    Ok(out)
}

pub fn ansi_fg(c: Color) -> String {
    match c {
        Color::Named(n) => {
            let code = match n {
                NamedColor::Black => 30,
                NamedColor::Red => 31,
                NamedColor::Green => 32,
                NamedColor::Yellow => 33,
                NamedColor::Blue => 34,
                NamedColor::Magenta => 35,
                NamedColor::Cyan => 36,
                NamedColor::Gray => 37,
                NamedColor::DarkGray => 90,
                NamedColor::LightRed => 91,
                NamedColor::LightGreen => 92,
                NamedColor::LightYellow => 93,
                NamedColor::LightBlue => 94,
                NamedColor::LightMagenta => 95,
                NamedColor::LightCyan => 96,
                NamedColor::White => 97,
            };
            format!("\x1b[{}m", code)
        }
        Color::Rgb(Rgb(r, g, b)) => format!("\x1b[38;2;{};{};{}m", r, g, b),
    }
}

pub fn reset() -> &'static str { "\x1b[0m" }

pub fn default_palette() -> Vec<Color> {
