// Terminal control via ANSI escape codes and raw mode.

use std::io::{self, Read, Write};
use std::os::fd::{AsRawFd, RawFd};
use std::os::raw::{c_int, c_ulong, c_ushort};

pub struct Terminal {
    pub stdout: io::Stdout,
    pub stdin_fd: RawFd,
    original: termios,
    raw_enabled: bool,
    alt_enabled: bool,
}

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct winsize {
    ws_row: c_ushort,
    ws_col: c_ushort,
    ws_xpixel: c_ushort,
    ws_ypixel: c_ushort,
}

#[repr(C)]
#[derive(Clone, Copy)]
struct termios {
    c_iflag: u32,
    c_oflag: u32,
    c_cflag: u32,
    c_lflag: u32,
    c_line: u8,
    c_cc: [u8; 32],
    c_ispeed: u32,
    c_ospeed: u32,
}

extern "C" {
    fn tcgetattr(fd: c_int, termios_p: *mut termios) -> c_int;
    fn tcsetattr(fd: c_int, optional_actions: c_int, termios_p: *const termios) -> c_int;
    fn ioctl(fd: c_int, request: c_ulong, ...) -> c_int;
    fn isatty(fd: c_int) -> c_int;
}

const TIOCGWINSZ: c_ulong = 0x5413;
const TCSANOW: c_int = 0;
const ICANON: u32 = 0o0000002;
const ECHO: u32 = 0o0000010;
const ISIG: u32 = 0o0000001;
const IEXTEN: u32 = 0o0100000;
const IXON: u32 = 0o0002000;
const ICRNL: u32 = 0o0000400;
const BRKINT: u32 = 0o0000002;
const INPCK: u32 = 0o0000020;
const ISTRIP: u32 = 0o0000040;
const OPOST: u32 = 0o0000001;
const CS8: u32 = 0o0000060;

impl Terminal {
    pub fn new() -> io::Result<Self> {
        let stdin_fd = std::io::stdin().as_raw_fd();
        let mut orig: termios = unsafe { std::mem::zeroed() };
        let ok = unsafe { tcgetattr(stdin_fd, &mut orig) };
        if ok != 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(Terminal {
            stdout: io::stdout(),
            stdin_fd,
            original: orig,
            raw_enabled: false,
            alt_enabled: false,
        })
    }

    pub fn size(&self) -> io::Result<(u16, u16)> {
        let mut ws: winsize = winsize::default();
        let ok = unsafe { ioctl(self.stdin_fd, TIOCGWINSZ, &mut ws as *mut _) };
        if ok != 0 {
            return Err(io::Error::last_os_error());
        }
        Ok((ws.ws_col, ws.ws_row))
    }

    pub fn enable_raw(&mut self) -> io::Result<()> {
        let mut t = self.original;
        t.c_iflag &= !(BRKINT | ICRNL | INPCK | ISTRIP | IXON);
        t.c_oflag &= !OPOST;
        t.c_cflag |= CS8;
        t.c_lflag &= !(ECHO | ICANON | IEXTEN | ISIG);
        t.c_cc[6] = 0; // VMIN
        t.c_cc[5] = 1; // VTIME (0.1s)
        let ok = unsafe { tcsetattr(self.stdin_fd, TCSANOW, &t) };
        if ok != 0 { return Err(io::Error::last_os_error()); }
        self.raw_enabled = true;
        Ok(())
    }

    pub fn disable_raw(&mut self) {
        if self.raw_enabled {
            let orig = self.original;
            unsafe { tcsetattr(self.stdin_fd, TCSANOW, &orig); }
            self.raw_enabled = false;
        }
    }

    pub fn enter_alt(&mut self) -> io::Result<()> {
        // Enter alt screen, hide cursor
        self.stdout.write_all(b"\x1b[?1049h")?;
        self.stdout.write_all(b"\x1b[?25l")?;
        self.stdout.flush()?;
        self.alt_enabled = true;
        Ok(())
    }

    pub fn leave_alt(&mut self) {
        if self.alt_enabled {
            let _ = self.stdout.write_all(b"\x1b[?25h");
            let _ = self.stdout.write_all(b"\x1b[?1049l");
            let _ = self.stdout.flush();
            self.alt_enabled = false;
        }
    }

    pub fn clear(&mut self) -> io::Result<()> {
        self.stdout.write_all(b"\x1b[2J\x1b[H")?;
        Ok(())
    }

    pub fn move_to(&mut self, x: u16, y: u16) -> io::Result<()> {
        write!(self.stdout, "\x1b[{};{}H", y + 1, x + 1)
    }
}

impl Drop for Terminal {
    fn drop(&mut self) {
        self.leave_alt();
        self.disable_raw();
    }
}

pub fn stdin_is_tty() -> bool {
    unsafe { isatty(0) == 1 }
}

pub fn stdout_is_tty() -> bool {
    unsafe { isatty(1) == 1 }
}

/// Try to read a key byte from stdin in non-blocking fashion, returns None if nothing.
pub fn read_key_nonblocking() -> Option<u8> {
    use std::os::unix::io::AsRawFd;
    let stdin = io::stdin();
    let fd = stdin.as_raw_fd();
    // Use poll to check
    #[repr(C)]
    struct pollfd { fd: c_int, events: i16, revents: i16 }
    extern "C" {
        fn poll(fds: *mut pollfd, nfds: c_ulong, timeout: c_int) -> c_int;
    }
    const POLLIN: i16 = 0x0001;
    let mut pfd = pollfd { fd, events: POLLIN, revents: 0 };
    let r = unsafe { poll(&mut pfd as *mut _, 1, 0) };
    if r > 0 && (pfd.revents & POLLIN) != 0 {
        let mut b = [0u8; 1];
        match stdin.lock().read(&mut b) {
            Ok(1) => Some(b[0]),
            _ => None,
        }
    } else {
        None
    }
}
