        t.c_lflag &= !(ECHO | ICANON | IEXTEN | ISIG);
        t.c_cc[6] = 0; // VMIN
        t.c_cc[5] = 1; // VTIME (0.1s)
        let ok = unsafe { tcsetattr(self.stdin_fd, TCSANOW, &t) };
        if ok != 0 { return Err(io::Error::last_os_error()); }
        self.raw_enabled = true;
        Ok(())
    }

