// Minimal TUI: renders a graph of ping/cmd timings with stats header and time axis.

use crate::cli::Args;
use crate::color::{self, Color};
use crate::term::{self, Terminal};
use crate::{mkerr, mkerr2, AppError};
use std::io::{self, BufRead, BufReader, Write};
use std::net::IpAddr;
use std::process::{Command, Stdio};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Clone, Copy)]
enum Sample {
    Ok(f64),     // microseconds
    Timeout,
}

struct Series {
    label: String,
    samples: Vec<(Instant, Sample)>,
    timeouts: u64,
}

fn spawn_pinger(
    target: String,
    label: String,
    args_ref: &Args,
    series: Arc<Mutex<Series>>,
    start: Instant,
) -> io::Result<()> {
    let mut cmd = Command::new("ping");
    // Build args based on flags
    if args_ref.ipv4 { cmd.arg("-4"); }
    if args_ref.ipv6 { cmd.arg("-6"); }
    if let Some(iface) = &args_ref.interface {
        cmd.arg("-I").arg(iface);
    }
    // Watch interval
    let interval = args_ref.watch_interval.unwrap_or(0.2);
    cmd.arg("-i").arg(format!("{}", interval.max(0.001)));
    for a in &args_ref.ping_args { cmd.arg(a); }
    cmd.arg(&target);
    cmd.stdout(Stdio::piped()).stderr(Stdio::piped());
    let mut child = cmd.spawn().map_err(|e| {
        io::Error::new(io::ErrorKind::Other, format!("Error spawning ping: {}", e))
    })?;
    let stdout = child.stdout.take().unwrap();
    thread::spawn(move || {
        let reader = BufReader::new(stdout);
        for line in reader.lines().flatten() {
            // look for "time=... ms"
            if let Some(idx) = line.find("time=") {
                let rest = &line[idx + 5..];
                let num: String = rest.chars().take_while(|c| c.is_ascii_digit() || *c == '.').collect();
                if let Ok(ms) = num.parse::<f64>() {
                    let mut s = series.lock().unwrap();
                    s.samples.push((Instant::now(), Sample::Ok(ms * 1000.0)));
                }
            }
        }
    });
    Ok(())
}

fn spawn_cmd(
    shell_cmd: String,
    label: String,
    args_ref: &Args,
    series: Arc<Mutex<Series>>,
    _start: Instant,
) {
    let interval = args_ref.watch_interval.unwrap_or(0.5);
    thread::spawn(move || {
        loop {
            let t0 = Instant::now();
            let status = Command::new("sh").arg("-c").arg(&shell_cmd)
                .stdout(Stdio::null()).stderr(Stdio::null()).stdin(Stdio::null()).status();
            let dt = t0.elapsed();
            let mut s = series.lock().unwrap();
            match status {
                Ok(st) if st.success() => {
                    s.samples.push((Instant::now(), Sample::Ok(dt.as_secs_f64() * 1_000_000.0)));
                }
                _ => {
                    s.samples.push((Instant::now(), Sample::Timeout));
                    s.timeouts += 1;
                }
            }
            drop(s);
            let elapsed = t0.elapsed();
            let sleep = Duration::from_secs_f64(interval);
            if elapsed < sleep { thread::sleep(sleep - elapsed); }
        }
    });
}

pub fn run_ping(
    args: &Args,
    resolved: &[(String, String, Vec<IpAddr>)],
    colors: &[Color],
) -> Result<(), AppError> {
    let mut series_vec: Vec<Arc<Mutex<Series>>> = Vec::new();
    let start = Instant::now();
    for (label, target, _ips) in resolved {
        let series = Arc::new(Mutex::new(Series {
            label: label.clone(),
            samples: Vec::new(),
            timeouts: 0,
        }));
        spawn_pinger(target.clone(), label.clone(), args, series.clone(), start)
            .map_err(|e| {
                let s = e.to_string();
                let core = s.strip_prefix("Error spawning ping: ").unwrap_or(&s).to_string();
                AppError { message: format!("Error spawning ping: {}", core), cause: Some(core) }
            })?;
        series_vec.push(series);
    }
    tui_loop(args, &series_vec, colors)
}

pub fn run_cmd(args: &Args, colors: &[Color]) -> Result<(), AppError> {
    let mut series_vec: Vec<Arc<Mutex<Series>>> = Vec::new();
    let start = Instant::now();
    for c in &args.hosts_or_commands {
        let series = Arc::new(Mutex::new(Series {
            label: c.clone(),
            samples: Vec::new(),
            timeouts: 0,
        }));
        spawn_cmd(c.clone(), c.clone(), args, series.clone(), start);
        series_vec.push(series);
    }
    tui_loop(args, &series_vec, colors)
}

fn tui_loop(args: &Args, series: &[Arc<Mutex<Series>>], colors: &[Color]) -> Result<(), AppError> {
    let mut term = Terminal::new().map_err(|e| mkerr(e.to_string()))?;
    term.enable_raw().map_err(|e| mkerr(e.to_string()))?;
    term.enter_alt().map_err(|e| mkerr(e.to_string()))?;

    let start = Instant::now();
    let buffer = Duration::from_secs(args.buffer.max(1));
    let palette = color::default_palette();

    loop {
        // handle input
        if let Some(k) = term::read_key_nonblocking() {
            if k == b'q' || k == 27 || k == 3 {
                break;
            }
        }
        let size = term.size().map_err(|e| mkerr(e.to_string()))?;
        let out = render(args, series, colors, &palette, size, start, buffer);
        {
            let _ = term.clear();
            let _ = term.stdout.write_all(out.as_bytes());
            let _ = term.stdout.flush();
        }
        thread::sleep(Duration::from_millis(100));
    }

    if args.clear {
        let _ = term.clear();
    }
    drop(term);
    Ok(())
}

fn render(
    args: &Args,
    series: &[Arc<Mutex<Series>>],
    colors: &[Color],
    palette: &[Color],
    size: (u16, u16),
    _start: Instant,
    buffer: Duration,
) -> String {
    let (cols, rows) = (size.0 as usize, size.1 as usize);
    let mut s = String::new();
    let hmargin = args.horizontal_margin as usize;
    let vmargin = args.vertical_margin as usize;
    // Header lines: one per series
    let n = series.len();
    let header_lines = n;
    // x-axis label line below and time labels line
    let bottom_lines = 2;
    if rows <= header_lines + bottom_lines + vmargin * 2 + 2 { return s; }

    // Stats header
    for (i, ser) in series.iter().enumerate() {
        let ser = ser.lock().unwrap();
        let c = pick_color(colors, palette, i);
        let esc = color::ansi_fg(c);
        let reset = color::reset();
        let stats = compute_stats(&ser);
        let label = ser.label.clone();
        let label_w = 30usize;
        let lab = if label.len() > label_w { label[..label_w].to_string() } else { format!("{:<w$}", label, w = label_w) };
        let line = format!(
            "{}{}{} last {}   min {}   max {}   avg {}   jtr {}   p95 {}   t/o {}",
            esc, lab, reset,
            fmt_us(stats.last), fmt_us(stats.min), fmt_us(stats.max),
            fmt_us(stats.avg), fmt_us(stats.jtr), fmt_us(stats.p95), stats.timeouts
        );
        s.push_str(&line);
        s.push_str("\r\n");
    }

    // Compute y-range from all samples within window
    let now = Instant::now();
    let window_start = now.checked_sub(buffer).unwrap_or(now);
    let mut all = Vec::new();
    for ser in series {
        let ser = ser.lock().unwrap();
        for (t, sa) in &ser.samples {
            if *t < window_start { continue; }
            if let Sample::Ok(v) = sa { all.push(*v); }
        }
    }
    let (ymin, ymax) = if all.is_empty() {
        (0.0, 1000.0)
    } else {
        let mn = all.iter().cloned().fold(f64::INFINITY, f64::min);
        let mx = all.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
        let span = (mx - mn).max(1.0);
        (mn - span * 0.1, mx + span * 0.1)
    };

    // Graph area
    let graph_top = header_lines + vmargin;
    let graph_bottom = rows.saturating_sub(bottom_lines + vmargin);
    let graph_left = 7 + hmargin; // room for y-axis labels
    let graph_right = cols.saturating_sub(hmargin);
    let graph_w = graph_right.saturating_sub(graph_left);
    let graph_h = graph_bottom.saturating_sub(graph_top);

    // Y-axis labels & left border
    for row in 0..graph_h {
        let y = ymax - (ymax - ymin) * (row as f64 / (graph_h - 1).max(1) as f64);
        let label = fmt_us(y);
        s.push_str(&format!("{:>6} │", label));
        // blank line content
        s.push_str(&" ".repeat(graph_w));
        s.push_str("\r\n");
    }
    // X-axis
    s.push_str(&format!("{:>6} └", ""));
    s.push_str(&"─".repeat(graph_w));
    s.push_str("\r\n");
    // Time labels
    let t_start = fmt_time_short(now - buffer);
    let t_mid = fmt_time_short(now - buffer / 2);
    let t_end = fmt_time_short(now);
    let spacer1 = graph_w.saturating_sub(8 * 3) / 2;
    s.push_str(&format!("{}{}{}{}{}\r\n",
        t_start,
        " ".repeat(spacer1),
        t_mid,
        " ".repeat(spacer1),
        t_end));

    s
}

struct Stats {
    last: f64,
    min: f64,
    max: f64,
    avg: f64,
    jtr: f64,
    p95: f64,
    timeouts: u64,
}

fn compute_stats(ser: &Series) -> Stats {
    let vals: Vec<f64> = ser.samples.iter().filter_map(|(_, s)| match s {
        Sample::Ok(v) => Some(*v), _ => None,
    }).collect();
    if vals.is_empty() {
        return Stats { last: 0.0, min: 0.0, max: 0.0, avg: 0.0, jtr: 0.0, p95: 0.0, timeouts: ser.timeouts };
    }
    let last = *vals.last().unwrap();
    let min = vals.iter().cloned().fold(f64::INFINITY, f64::min);
    let max = vals.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let avg = vals.iter().sum::<f64>() / vals.len() as f64;
    // jitter = mean absolute diff
    let jtr = if vals.len() < 2 { 0.0 } else {
        let mut sum = 0.0f64;
        for w in vals.windows(2) { sum += (w[1] - w[0]).abs(); }
        sum / (vals.len() - 1) as f64
    };
    let p95 = {
        let mut v = vals.clone();
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        let idx = ((v.len() as f64) * 0.95).floor() as usize;
        v[idx.min(v.len() - 1)]
    };
    Stats { last, min, max, avg, jtr, p95, timeouts: ser.timeouts }
}

fn fmt_us(v: f64) -> String {
    if v <= 0.0 { return "0ns".into(); }
    if v < 1.0 {
        let ns = (v * 1000.0) as i64;
        return format!("{}ns", ns);
    }
    if v < 1000.0 {
        return format!("{}µs", v as i64);
    }
    if v < 1_000_000.0 {
        return format!("{:.0}ms", v / 1000.0);
    }
    format!("{:.1}s", v / 1_000_000.0)
}

fn pick_color(colors: &[Color], palette: &[Color], i: usize) -> Color {
    if i < colors.len() { colors[i] }
    else { palette[i % palette.len()] }
}

fn fmt_time_short(t: Instant) -> String {
    // Approximate wall-clock time from Instant.
    // We'll use SystemTime directly.
    let now = std::time::SystemTime::now();
    // Adjust based on difference from Instant now
    let diff = Instant::now().duration_since(t);
    let wall = now.checked_sub(diff).unwrap_or(now);
    let secs = wall.duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_secs();
    let (_, _, _, h, m, s) = decompose_time(secs);
    format!("{:02}:{:02}:{:02}", h, m, s)
}

fn decompose_time(secs: u64) -> (u64, u64, u64, u64, u64, u64) {
    let s = secs % 60;
    let m = (secs / 60) % 60;
    let h = (secs / 3600) % 24;
    // (date parts approximate, unused)
    (0, 0, 0, h, m, s)
}
