        return format!("{}ns", ns);
    }
    if v < 1000.0 {
        return format!("{}µs", v as i64);
    }
    if v < 1_000_000.0 {
        return format!("{:.0}ms", v / 1000.0);
    }
    format!("{:.1}s", v / 1_000_000.0)
}

fn pick_color(colors: &[Color], palette: &[Color], i: usize) -> Color {
    if i < colors.len() { colors[i] }
    else { palette[i % palette.len()] }
}

fn fmt_time_short(t: Instant) -> String {
    // Approximate wall-clock time from Instant.
    // We'll use SystemTime directly.
    let now = std::time::SystemTime::now();
    // Adjust based on difference from Instant now
    let diff = Instant::now().duration_since(t);
    let wall = now.checked_sub(diff).unwrap_or(now);
    let secs = wall.duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_secs();
    let (_, _, _, h, m, s) = decompose_time(secs);
    format!("{:02}:{:02}:{:02}", h, m, s)
}

fn decompose_time(secs: u64) -> (u64, u64, u64, u64, u64, u64) {
    let s = secs % 60;
    let m = (secs / 60) % 60;
    let h = (secs / 3600) % 24;
    // (date parts approximate, unused)
    (0, 0, 0, h, m, s)
}
