// Describe positional-part for usage briefs.
fn pos_part(has_pos: bool) -> &'static str {
    if has_pos { "<HOSTS_OR_COMMANDS>..." } else { "[HOSTS_OR_COMMANDS]..." }
}

fn usage_line_default(prog: &str) -> String {
    format!("Usage: {} [OPTIONS] [HOSTS_OR_COMMANDS]...", prog)
}

fn usage_line_active(prog: &str, active: &str, has_pos: bool) -> String {
    format!("Usage: {} {} {}", prog, active, pos_part(has_pos))
}

fn err_unexpected(prog: &str, tok: &str) -> CliError {
    let mut s = String::new();
    s.push_str(&format!("error: unexpected argument '{}' found\n\n", tok));
    s.push_str(&format!("  tip: to pass '{}' as a value, use '-- {}'\n\n", tok, tok));
    s.push_str(&usage_line_default(prog));
    s.push_str("\n\nFor more information, try '--help'.\n");
    CliError::Usage(s)
}

fn err_value_required(name: &str) -> CliError {
    let s = format!(
        "error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.\n",
        name
    );
    CliError::Usage(s)
}

fn err_multiple(prog: &str, name: &str) -> CliError {
    let mut s = String::new();
    s.push_str(&format!("error: the argument '{}' cannot be used multiple times\n\n", name));
    s.push_str(&usage_line_default(prog));
    s.push_str("\n\nFor more information, try '--help'.\n");
    CliError::Usage(s)
}

fn err_conflict(prog: &str, active: &str, new: &str, has_pos: bool) -> CliError {
    let mut s = String::new();
    s.push_str(&format!("error: the argument '{}' cannot be used with '{}'\n\n", active, new));
    s.push_str(&usage_line_active(prog, active, has_pos));
    s.push_str("\n\nFor more information, try '--help'.\n");
    CliError::Usage(s)
}

fn err_invalid_value(name: &str, val: &str, reason: &str) -> CliError {
    let s = format!(
        "error: invalid value '{}' for '{}': {}\n\nFor more information, try '--help'.\n",
        val, name, reason
    );
    CliError::Usage(s)
}

fn parse_uint(s: &str, display: &str) -> Result<u64, CliError> {
    if s.is_empty() {
        return Err(err_invalid_value(display, s, "cannot parse integer from empty string"));
    }
    if s.starts_with('-') {
        return Err(err_invalid_value(display, s, "invalid digit found in string"));
    }
    // plus sign not observed; treat as invalid digit
    let s_check = s.strip_prefix('+').unwrap_or(s);
    for c in s_check.chars() {
        if !c.is_ascii_digit() {
            return Err(err_invalid_value(display, s, "invalid digit found in string"));
        }
    }
    match s_check.parse::<u64>() {
        Ok(v) => Ok(v),
        Err(_) => Err(err_invalid_value(display, s, "number too large to fit in target type")),
    }
}

fn parse_u16_arg(s: &str, display: &str) -> Result<u16, CliError> {
    let v = parse_uint(s, display)?;
    if v > u16::MAX as u64 {
        return Err(err_invalid_value(display, s, "number too large to fit in target type"));
    }
    Ok(v as u16)
}

fn parse_float(s: &str, display: &str) -> Result<f64, CliError> {
    match s.parse::<f64>() {
        Ok(v) => Ok(v),
        Err(_) => Err(err_invalid_value(display, s, "invalid float literal")),
    }
}

// Option displays used in errors
const D_WATCH: &str = "--watch-interval <WATCH_INTERVAL>";
const D_BUF: &str = "--buffer <BUFFER>";
const D_IFACE: &str = "--interface <INTERFACE>";
const D_VM: &str = "--vertical-margin <VERTICAL_MARGIN>";
const D_HM: &str = "--horizontal-margin <HORIZONTAL_MARGIN>";
const D_COLOR: &str = "--color <color>";
const D_CMD: &str = "--cmd";
const D_SIMPLE: &str = "--simple-graphics";
const D_CLEAR: &str = "--clear";
const D_PING: &str = "--ping-args [<PING_ARGS>...]";
const D_4: &str = "-4";
const D_6: &str = "-6";

pub fn parse(input: &[String], prog: &str) -> Result<ParseResult, CliError> {
    let mut cmd = false;
    let mut watch_interval: Option<f64> = None;
    let mut buffer: Option<u64> = None;
    let mut ipv4 = false;
    let mut ipv6 = false;
    let mut interface: Option<String> = None;
    let mut simple_graphics = false;
    let mut vertical_margin: Option<u16> = None;
    let mut horizontal_margin: Option<u16> = None;
    let mut colors: Vec<String> = Vec::new();
    let mut clear = false;
    let mut ping_args_given = false;
    let mut ping_args: Vec<String> = Vec::new();
    let mut hosts: Vec<String> = Vec::new();

    let mut i = 0;
    let mut after_dd = false;
    while i < input.len() {
        let arg = input[i].clone();
        if after_dd {
            hosts.push(arg);
            i += 1;
            continue;
        }
        if arg == "--" {
            after_dd = true;
            i += 1;
            continue;
        }
        if arg.starts_with("--") {
            let (name, val_opt) = match arg.find('=') {
                Some(idx) => (arg[..idx].to_string(), Some(arg[idx + 1..].to_string())),
                None => (arg.clone(), None),
            };
            let has_pos_so_far = !hosts.is_empty();
            match name.as_str() {
                "--help" => return Ok(ParseResult::Help),
                "--version" => return Ok(ParseResult::LongVersion),
                "--cmd" => {
                    if val_opt.is_some() {
                        return Err(err_invalid_value("--cmd", val_opt.as_ref().unwrap(), "expected no argument"));
                    }
                    if cmd { return Err(err_multiple(prog, D_CMD)); }
                    if ping_args_given { return Err(err_conflict(prog, D_PING, D_CMD, has_pos_so_far)); }
                    cmd = true;
                    i += 1;
                }
                "--watch-interval" => {
                    let v = take_value(&name, val_opt, input, &mut i, D_WATCH)?;
                    if watch_interval.is_some() { return Err(err_multiple(prog, D_WATCH)); }
                    watch_interval = Some(parse_float(&v, D_WATCH)?);
                }
                "--buffer" => {
                    let v = take_value(&name, val_opt, input, &mut i, D_BUF)?;
                    if buffer.is_some() { return Err(err_multiple(prog, D_BUF)); }
                    buffer = Some(parse_uint(&v, D_BUF)?);
                }
                "--interface" => {
                    let v = take_value(&name, val_opt, input, &mut i, D_IFACE)?;
                    if interface.is_some() { return Err(err_multiple(prog, D_IFACE)); }
                    interface = Some(v);
                }
                "--simple-graphics" => {
                    if val_opt.is_some() {
                        return Err(err_invalid_value("--simple-graphics", val_opt.as_ref().unwrap(), "expected no argument"));
                    }
                    if simple_graphics { return Err(err_multiple(prog, D_SIMPLE)); }
                    simple_graphics = true;
                    i += 1;
                }
                "--vertical-margin" => {
                    let v = take_value(&name, val_opt, input, &mut i, D_VM)?;
                    if vertical_margin.is_some() { return Err(err_multiple(prog, D_VM)); }
                    vertical_margin = Some(parse_u16_arg(&v, D_VM)?);
                }
                "--horizontal-margin" => {
                    let v = take_value(&name, val_opt, input, &mut i, D_HM)?;
                    if horizontal_margin.is_some() { return Err(err_multiple(prog, D_HM)); }
                    horizontal_margin = Some(parse_u16_arg(&v, D_HM)?);
                }
                "--color" => {
                    let v = take_value(&name, val_opt, input, &mut i, D_COLOR)?;
                    if !v.is_empty() {
                        for c in v.split(',') {
                            colors.push(c.to_string());
                        }
                    }
                }
                "--clear" => {
                    if val_opt.is_some() {
                        return Err(err_invalid_value("--clear", val_opt.as_ref().unwrap(), "expected no argument"));
                    }
                    if clear { return Err(err_multiple(prog, D_CLEAR)); }
                    clear = true;
                    i += 1;
                }
                "--ping-args" => {
                    if cmd { return Err(err_conflict(prog, D_CMD, D_PING, has_pos_so_far)); }
                    if ping_args_given { return Err(err_multiple(prog, D_PING)); }
                    ping_args_given = true;
                    if let Some(val) = val_opt {
                        if !val.is_empty() {
                            ping_args.push(val);
                        }
                        i += 1;
                    } else {
                        i += 1;
                        while i < input.len() {
                            let nxt = &input[i];
                            if nxt == "--" { break; }
                            // stop at any arg that starts with '-' followed by a letter or digit (flag-looking)
                            if nxt.starts_with('-') && nxt.len() > 1 {
                                break;
                            }
                            ping_args.push(nxt.clone());
                            i += 1;
                        }
                    }
                }
                _ => {
                    return Err(err_unexpected(prog, &arg));
                }
            }
        } else if arg.starts_with('-') && arg.len() > 1 && arg != "-" {
            let rest = &arg[1..];
            let first = rest.chars().next().unwrap();
            if first.is_ascii_digit() && first != '4' && first != '6' {
                return Err(err_unexpected(prog, &arg));
            }
            let chars: Vec<char> = rest.chars().collect();
            let mut idx = 0;
            while idx < chars.len() {
                let c = chars[idx];
                let has_pos_so_far = !hosts.is_empty();
                match c {
                    'h' => return Ok(ParseResult::Help),
                    'V' => return Ok(ParseResult::ShortVersion),
                    's' => {
                        if simple_graphics { return Err(err_multiple(prog, D_SIMPLE)); }
                        simple_graphics = true;
                        idx += 1;
                    }
                    '4' => {
                        if ipv4 { return Err(err_multiple(prog, D_4)); }
                        if ipv6 { return Err(err_conflict(prog, D_6, D_4, has_pos_so_far)); }
                        ipv4 = true;
                        idx += 1;
                    }
                    '6' => {
                        if ipv6 { return Err(err_multiple(prog, D_6)); }
                        if ipv4 { return Err(err_conflict(prog, D_4, D_6, has_pos_so_far)); }
                        ipv6 = true;
                        idx += 1;
                    }
                    'n' | 'b' | 'i' | 'c' => {
                        let display = match c {
                            'n' => D_WATCH,
                            'b' => D_BUF,
                            'i' => D_IFACE,
                            'c' => D_COLOR,
                            _ => unreachable!(),
                        };
                        let val: String;
                        if idx + 1 < chars.len() {
                            val = chars[idx + 1..].iter().collect();
                            idx = chars.len();
                        } else {
                            if i + 1 >= input.len() {
                                return Err(err_value_required(display));
                            }
                            i += 1;
                            val = input[i].clone();
                            idx = chars.len();
                        }
                        match c {
                            'n' => {
                                if watch_interval.is_some() { return Err(err_multiple(prog, display)); }
                                watch_interval = Some(parse_float(&val, display)?);
                            }
                            'b' => {
                                if buffer.is_some() { return Err(err_multiple(prog, display)); }
                                buffer = Some(parse_uint(&val, display)?);
                            }
                            'i' => {
                                if interface.is_some() { return Err(err_multiple(prog, display)); }
                                interface = Some(val);
                            }
                            'c' => {
                                if !val.is_empty() {
                                    for cc in val.split(',') { colors.push(cc.to_string()); }
                                }
                            }
                            _ => unreachable!(),
                        }
                    }
                    _ => {
                        let tok = format!("-{}", c);
                        return Err(err_unexpected(prog, &tok));
                    }
                }
            }
            i += 1;
        } else {
            hosts.push(arg);
            i += 1;
        }
    }

    Ok(ParseResult::Args(Args {
        cmd,
        watch_interval,
        buffer: buffer.unwrap_or(30),
        ipv4,
        ipv6,
        interface,
        simple_graphics,
        vertical_margin: vertical_margin.unwrap_or(1),
        horizontal_margin: horizontal_margin.unwrap_or(0),
        colors,
        clear,
        ping_args,
        hosts_or_commands: hosts,
    }))
}

fn take_value(
    _name: &str,
    val_opt: Option<String>,
    input: &[String],
    i: &mut usize,
    display: &str,
) -> Result<String, CliError> {
    if let Some(v) = val_opt {
        *i += 1;
        return Ok(v);
    }
    if *i + 1 >= input.len() {
        return Err(err_value_required(display));
    }
    *i += 2;
    Ok(input[*i - 1].clone())
}
