# Replace Terminal::new to open /dev/tty
old = '''impl Terminal {
    pub fn new() -> io::Result<Self> {
        let stdin_fd = std::io::stdin().as_raw_fd();
        let mut orig: termios = unsafe { std::mem::zeroed() };
        let ok = unsafe { tcgetattr(stdin_fd, &mut orig) };
        if ok != 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(Terminal {
            stdout: io::stdout(),
            stdin_fd,
            original: orig,
            raw_enabled: false,
            alt_enabled: false,
        })
    }'''
new = '''impl Terminal {
    pub fn new() -> io::Result<Self> {
        // Open /dev/tty for terminal I/O, matching typical TUI library behavior.
        let tty = std::fs::OpenOptions::new().read(true).write(true).open("/dev/tty")?;
        let fd = tty.as_raw_fd();
        let mut orig: termios = unsafe { std::mem::zeroed() };
        let ok = unsafe { tcgetattr(fd, &mut orig) };
        if ok != 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(Terminal {
            stdout: io::stdout(),
            tty_file: tty,
            stdin_fd: fd,
            original: orig,
            raw_enabled: false,
            alt_enabled: false,
        })
    }'''
c = c.replace(old, new)

# Add tty_file field to Terminal struct
old = '''pub struct Terminal {
    pub stdout: io::Stdout,
    pub stdin_fd: RawFd,
    original: termios,
    raw_enabled: bool,
    alt_enabled: bool,
}'''
new = '''pub struct Terminal {
    pub stdout: io::Stdout,
    pub tty_file: std::fs::File,
    pub stdin_fd: RawFd,
    original: termios,
    raw_enabled: bool,
    alt_enabled: bool,
}'''
c = c.replace(old, new)

with open('src/term.rs','w') as f:
    f.write(c)
print("patched")
